// Spec pages render spec/*.md at /spec/<file> and spec/milestones/*.md at /roadmap/<file>. Links between them stay
// on the site and links to the rest of the repository go to GitHub. The page header shows the title, status and specs,
// so the file's own (generated by scripts/spec_index.py) are left out.
import { posix } from "node:path"

import { visit } from "unist-util-visit"

const BACKGROUND = /^spec\/([a-z][\w-]*)\.md$/

/** Where a link from `file` (a path in the repository) to `url` goes on the site; `blob` is the repository's files. */
function siteUrl(file, url, blob) {
  const [path, anchor = ""] = url.split(/(?=#)/)
  const target = posix.normalize(posix.join(posix.dirname(file), path))
  const spec = target.match(/^spec\/(\d{4}-[\w-]+)\.md$/)
  if (spec) return `/spec/${spec[1]}${anchor}`
  const milestone = target.match(/^spec\/milestones\/([\w-]+)\.md$/)
  if (milestone) return (milestone[1] === "README" ? "/roadmap" : `/roadmap/${milestone[1]}`) + anchor
  if (target === "spec/README.md") return `/spec${anchor}`
  const page = target.match(BACKGROUND)
  if (page && page[1] !== "TEMPLATE") return `/spec/${page[1]}${anchor}`
  return blob + target + anchor
}

/** `repo` is the repository's URL on GitHub (REPO_URL in lib/site.ts, passed in by next.config.ts). */
export default function remarkSpec({ repo }) {
  const blob = `${repo}/blob/main/`
  return (tree, file) => {
    const path = (file.path ?? "").replaceAll("\\", "/")
    const match = path.match(/\/(spec\/(?:milestones\/)?[^/]+\.md)$/)
    if (!match) return
    const title = tree.children.findIndex((n) => n.type === "heading" && n.depth === 1)
    if (title >= 0) {
      // The title, and the status line under it (`**Done** · updated …`).
      const next = tree.children[title + 1]
      const statusLine = next?.type === "paragraph" && next.children[0]?.type === "strong"
      tree.children.splice(title, statusLine ? 2 : 1)
    }
    // A milestone's table of specs, which the page shows with their statuses.
    const start = tree.children.findIndex((n) => n.type === "html" && n.value.includes("specs:start"))
    const end = tree.children.findIndex((n) => n.type === "html" && n.value.includes("specs:end"))
    if (start >= 0 && end > start) tree.children.splice(start, end - start + 1)
    visit(tree, "link", (node) => {
      if (/^(https?:|mailto:|#|\/)/.test(node.url)) return
      node.url = siteUrl(match[1], node.url, blob)
    })
  }
}
